import React, { createContext, useContext } from "react";
import { useCurrentFrame } from "remotion";
import data from "./data/timeline.json";

/**
 * THE TIMELINE — single source of truth for every frame number in the film.
 *
 * src/data/timeline.json is generated by scripts/audio/build_timeline.py from the
 * recorded dialogue: the length of each recording decides where the next line, the
 * next shot and the next scene begin. Nothing in src/ hard-codes a dialogue frame;
 * scenes ask this module where a line or a hold is and animate relative to that.
 */

export type SpeakerId = "tile" | "detective" | "pattern" | "vanity" | "narrator";
export type SceneId = "hook" | "suspects" | "makeover" | "payoff" | "brand";
export type HoldId = "box" | "transform" | "compare";

export type Phrase = { text: string; from: number; to: number };
export type Line = {
  id: string;
  speaker: SpeakerId;
  /** Absolute film frames; `to` is exclusive. */
  from: number;
  to: number;
  seconds: number;
  file: string;
  text: string;
  speech: string;
  subtitle: boolean;
  brand: boolean;
  recorded: boolean;
  lipSource: string;
  phrases: Phrase[];
  /** One value per frame of the line: jaw opening, lip rounding, loudness (all 0..1). */
  open: number[];
  round: number[];
  energy: number[];
  words: { w: string; from: number; to: number }[];
};
export type SceneSpan = { id: SceneId; titleFa: string; from: number; to: number };

type TimelineFile = {
  fps: number;
  durationInFrames: number;
  seconds: number;
  allRecorded: boolean;
  scenes: SceneSpan[];
  holds: Record<string, { from: number; to: number }>;
  lines: Line[];
};

export const TL = data as unknown as TimelineFile;
export const FPS = TL.fps;
export const DURATION = TL.durationInFrames;
export const LINES = TL.lines;

const lineById = new Map(TL.lines.map((l) => [l.id, l]));
const sceneById = new Map(TL.scenes.map((s) => [s.id, s]));

export const line = (id: string): Line => {
  const l = lineById.get(id);
  if (!l) throw new Error(`timeline: unknown line ${id}`);
  return l;
};
export const scene = (id: SceneId): SceneSpan => {
  const s = sceneById.get(id);
  if (!s) throw new Error(`timeline: unknown scene ${id}`);
  return s;
};
export const hold = (id: HoldId) => {
  const h = TL.holds[id];
  if (!h) throw new Error(`timeline: unknown hold ${id}`);
  return h;
};

export type Mouth = { open: number; round: number; energy: number; speaking: boolean };
const SILENT: Mouth = { open: 0, round: 0, energy: 0, speaking: false };

/** Mouth pose of one line at an absolute film frame. */
export const mouthOf = (id: string, f: number): Mouth => {
  const l = line(id);
  const k = Math.floor(f) - l.from;
  if (k < 0 || k >= l.open.length) return SILENT;
  return { open: l.open[k], round: l.round[k], energy: l.energy[k], speaking: true };
};

/** Mouth pose of a character at an absolute film frame (whichever of its lines is playing). */
export const mouthFor = (speaker: SpeakerId, f: number): Mouth => {
  for (const l of TL.lines) {
    if (l.speaker === speaker && f >= l.from && f < l.to) return mouthOf(l.id, f);
  }
  return SILENT;
};

/** The line being spoken at frame f, if any. */
export const speakingAt = (f: number): Line | null => TL.lines.find((l) => f >= l.from && f < l.to) ?? null;

/** 0 while nobody speaks, 1 during speech, with a ramp of `ramp` frames on both sides (for music ducking). */
export const speechPresence = (f: number, ramp = 6, hangover = 5): number => {
  let v = 0;
  for (const l of TL.lines) {
    const a = l.from - ramp;
    const b = l.to + hangover;
    if (f < a || f > b + ramp) continue;
    const up = Math.min(1, (f - a) / ramp);
    const down = Math.min(1, (b + ramp - f) / ramp);
    v = Math.max(v, Math.max(0, Math.min(up, down)));
  }
  return v;
};

/* ------------------------------------------------------------------ */
/* Film-frame context: scenes live inside <Sequence>, which restarts   */
/* useCurrentFrame() at 0; this gives them the absolute film frame.    */
/* ------------------------------------------------------------------ */

const Offset = createContext(0);

export const FilmFrameOffset: React.FC<{ offset: number; children: React.ReactNode }> = ({ offset, children }) =>
  React.createElement(Offset.Provider, { value: offset }, children);

/** Absolute film frame, wherever the component sits in the Sequence tree. */
export const useFilmFrame = () => useCurrentFrame() + useContext(Offset);
